// STRATTON CANDIDATE ENGINE — CONFIG
// The same node appears at the head of all three workflows. Edit it in one, paste it
// into the other two; validate.py checks that they have not drifted apart.
//
// Any key left blank means that step is SKIPPED, not that the run fails. That is what
// lets the whole engine be demonstrated on a screen-share before a single credential,
// phone number or ATS sandbox exists.

// ---------------------------------------------------------------- Which client is this
// Everything the engine writes carries this id. One n8n instance runs every client;
// two clients can never see each other's rows because every query is filtered on it and
// every table has an RLS policy that says the same thing.
const CLIENT_SLUG = 'stratton';
const CLIENT_ID   = '';          // the clients.id uuid from Supabase. Blank -> demo mode.

// ---------------------------------------------------------------- Supabase
// SUPABASE_URL blank -> the engine runs against sample/ data and writes nothing.
const SUPABASE_URL          = '';   // https://xxxxxxxx.supabase.co
const SUPABASE_SERVICE_KEY  = '';   // service_role key. n8n credential store is better;
                                    // this is here so the template runs before that exists.

// ---------------------------------------------------------------- The ATS
// One block, six vendors. Only ATS_VENDOR and the credentials change between clients —
// the field mapping below is what actually makes a new ATS work.
const ATS_VENDOR   = 'bullhorn';    // bullhorn | avionte | ceipal | jobdiva | recruitcrm | salesforce | generic
const ATS_BASE_URL = '';            // e.g. https://rest99.bullhornstaffing.com/rest-services/abcde
const ATS_TOKEN    = '';            // BhRestToken / bearer. Blank -> ATS steps are skipped.

// How THIS client's ATS names things. This object is the entire onboarding cost of a new
// ATS: point each of our field names at theirs, dotted paths allowed.
const ATS_FIELDS = {
  job: {
    id:            'id',
    title:         'title',
    description:   'publicDescription',
    skills:        'skillList',            // comma string or array, both handled
    city:          'address.city',
    state:         'address.state',
    pay_rate:      'payRate',
    shift:         'customText1',
    employment:    'employmentType',
    recruiter:     'owner.name',
    recruiter_mail:'owner.email'
  },
  candidate: {
    id:         'id',
    first_name: 'firstName',
    last_name:  'lastName',
    email:      'email',
    phone:      'mobile',
    phone_alt:  'phone',
    title:      'occupation',
    skills:     'skillSet',
    city:       'address.city',
    state:      'address.state',
    status:     'status'
  }
};

// Where candidates come from when the ATS is not connected. The search endpoint per
// vendor differs; the shape after `normalise the candidates` does not.
const ATS_CANDIDATE_SEARCH_LIMIT = 200;   // ask the ATS for this many, score them all
const ENROLL_TOP_N               = 25;    // enroll only the best this many

// ---------------------------------------------------------------- The AI reader
// Most job orders are prose. `skillList` is empty far more often than a vendor demo
// suggests, and matching 20,000 candidates against an empty skill list finds nobody.
//
// So when the ATS gives us fewer than MIN_SKILLS_BEFORE_AI real skills, the description is
// read once and turned into a structured requirement list. It runs ONCE PER JOB ORDER, not
// per candidate — a few hundred tokens per campaign, not per person.
//
// Blank key -> the step is skipped and the keyword rules stand on their own.
const AI_API_KEY = '';
const AI_MODEL   = 'claude-opus-5';
const AI_EFFORT  = 'low';        // low | medium | high — extraction is not a hard problem
const MIN_SKILLS_BEFORE_AI = 2;  // at or below this many ATS skills, ask the model

// The model may only return skills. It is never asked who to contact, and never asked to
// score anybody — those stay in code where they can be audited and re-run.
const AI_MAX_SKILLS = 12;

// ---------------------------------------------------------------- Matching
// A transparent score, on purpose. A staffing manager can read why someone was
// contacted, which they cannot do with an embedding similarity.
const MATCH = {
  required_skill:   18,   // per required skill the candidate has
  nice_skill:        6,
  same_city:        12,
  same_state:        6,
  title_overlap:    14,   // words shared between their title and the job title
  recent_activity:  10,   // ATS status suggests they are actively looking
  has_mobile:        8    // no mobile means no SMS and no call. Weighted, not fatal.
};
const MIN_MATCH_SCORE = 40;   // below this, stored with a reason and never contacted

// Statuses in the client's ATS that mean "do not contact this person". Placed candidates
// are the one that gets people in trouble.
const ATS_EXCLUDE_STATUSES = ['Placed', 'Do Not Contact', 'Blacklisted', 'Inactive',
  'Deceased', 'Archived'];

// ---------------------------------------------------------------- The outreach ladder
// Copied onto the campaign at launch, so editing this never changes the behaviour of a
// campaign already running. delay_hours is measured from the previous attempt.
const SEQUENCE = [
  { step: 1, channel: 'sms',   delay_hours: 0,
    template: 'Hi {{first_name}}, it is {{recruiter_name}} at {{client_name}}. We have a '
            + '{{job_title}} role in {{job_city}}{{pay_phrase}}. Interested in hearing more? '
            + 'Reply YES or STOP to opt out.' },
  { step: 2, channel: 'sms',   delay_hours: 20,
    template: 'Hi {{first_name}}, following up on the {{job_title}} position in {{job_city}}. '
            + 'Still open. Reply YES and I will call you, or STOP to opt out.' },
  { step: 3, channel: 'voice', delay_hours: 26,
    agent_note: 'Second contact. They have had two texts and not replied. Keep it under '
              + '90 seconds and offer to text the details instead.' },
  { step: 4, channel: 'sms',   delay_hours: 48,
    template: 'Last note from me on the {{job_title}} role, {{first_name}} — reply YES if '
            + 'you would like the details, otherwise I will close it out. STOP to opt out.' }
];

// ---------------------------------------------------------------- When we are allowed
// TCPA is the reason this block exists. Quiet hours are evaluated in the CANDIDATE's
// timezone, not the server's and not the recruiter's.
const QUIET_HOURS_START = 21;    // no outbound at or after 21:00 local
const QUIET_HOURS_END   = 8;     // no outbound before 08:00 local
const SEND_ON_WEEKENDS  = false;
const DEFAULT_TIMEZONE  = 'America/New_York';

const RUNNER_BATCH_SIZE = 50;    // enrollments claimed per 15-minute run
const DAILY_SEND_CAP    = 500;   // hard ceiling per client per day, enforced in code
const LEASE_SECONDS     = 300;   // how long a claimed row stays claimed

// A number we have already touched today is not touched again, whatever the ladder says.
const MIN_HOURS_BETWEEN_TOUCHES = 18;

// ---------------------------------------------------------------- Twilio
const TWILIO_ACCOUNT_SID  = '';
const TWILIO_AUTH_TOKEN   = '';   // also the key the inbound webhook signature is checked with
const TWILIO_FROM_NUMBER  = '';   // +1XXXXXXXXXX, or a Messaging Service SID below
const TWILIO_MESSAGING_SID= '';   // MGxxxx. Preferred at volume — handles the number pool.
const TWILIO_STATUS_CALLBACK = '';// https://n8n.example.com/webhook/stratton-inbound

// Twilio error codes that mean "this will never work" — retrying them wastes money and
// looks like a loop. Everything else is treated as transient and backed off.
const PERMANENT_SMS_ERRORS = ['21211', '21610', '21614', '21408', '30003', '30005', '30006'];
//                            bad num  optout  not mobile geo-perm unreach  unknown  landline

// ---------------------------------------------------------------- Retell AI
const RETELL_API_KEY   = '';
const RETELL_AGENT_ID  = '';      // the outbound screening agent
const RETELL_FROM_NUMBER = '';    // a number bought inside Retell, or a Twilio number imported
const RETELL_WEBHOOK_SECRET = ''; // verifies the call_analyzed callback

// ---------------------------------------------------------------- Qualification
// The structured criteria. The AI agent is asked to fill these in; it is not asked to
// decide. The decision is this object, evaluated in a Code node, identically every time.
const QUALIFY = {
  must: [
    { key: 'interested',        equals: true,  label: 'said they are interested' },
    { key: 'authorized_to_work', equals: true, label: 'authorised to work' },
    { key: 'can_start_within_days', lte: 21,   label: 'can start within three weeks' }
  ],
  score: [
    { key: 'years_experience',  gte: 2,    points: 25, label: '2+ years experience' },
    { key: 'has_reliable_transport', equals: true, points: 15, label: 'has transport' },
    { key: 'shift_match',       equals: true, points: 20, label: 'shift works for them' },
    { key: 'rate_acceptable',   equals: true, points: 25, label: 'accepts the rate' },
    { key: 'certifications_valid', equals: true, points: 15, label: 'certifications current' }
  ],
  pass_mark: 60,
  // Anything the AI could not establish is null, and null never passes a `must`. An
  // unanswered question is a not-qualified, not an assumed yes.
  review_band: 15   // within this many points of the pass mark -> human review, not a rejection
};

// Words that stop everything, checked before anything else is done with a message.
const OPT_OUT_KEYWORDS = ['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit',
  'remove me', 'opt out', 'optout', 'do not text', 'dont text', 'take me off'];
const POSITIVE_KEYWORDS = ['yes', 'yeah', 'yep', 'y', 'sure', 'interested', 'ok', 'okay',
  'tell me more', 'more info', 'call me', 'sounds good', 'im in', "i'm in"];
const NEGATIVE_KEYWORDS = ['no', 'not interested', 'no thanks', 'nope', 'pass',
  'already have a job', 'found a job', 'not looking'];

// ---------------------------------------------------------------- Scheduling
const CALENDAR_PROVIDER   = 'google';   // google | microsoft | none
const RECRUITER_CALENDARS = {
  // recruiter email -> calendar id. Blank object -> the job order's recruiter_email is used
  // as the calendar id, which is what Google does by default anyway.
};
const INTERVIEW_MINUTES     = 30;
const BOOKING_LEAD_HOURS    = 18;    // never book sooner than this
const BOOKING_WINDOW_DAYS   = 5;     // look this far ahead for a slot
const BOOKING_HOURS         = [9, 10, 11, 13, 14, 15, 16];   // recruiter local hours

// ---------------------------------------------------------------- Telling people
const SLACK_WEBHOOK_URL = '';    // blank -> no Slack notification
const NOTIFY_RECRUITER_EMAIL = true;

// ---------------------------------------------------------------- The safety switch
// Ships in the safest position. Nothing reaches a candidate until someone deliberately
// changes TEST_RUN.
const TEST_RUN    = true;   // true -> no SMS, no call, no ATS write, no calendar event
const TEST_PHONE  = '';     // blank -> preview only. Set -> messages really send, to here.
const DRY_RUN_DB  = false;  // true -> Supabase reads happen, writes do not

// Gives every provider call a deterministic fake response so the three workflows can be
// watched end to end before any account exists. FORCES preview whatever the two above say,
// because a fabricated Twilio SID must never be able to reach a real phone.
const DEMO_MODE = true;

// Quiet hours are real, and at 01:00 the runner correctly defers every single row — which
// is the right behaviour and a useless thing to film. This ignores the quiet-hours check
// so a walkthrough can be recorded at any hour.
//
// It is honoured ONLY when DEMO_MODE is on, and DEMO_MODE forces preview, so this switch
// can never cause a real message at 3am. Turning DEMO_MODE off disarms it automatically.
const DEMO_ANY_HOUR = true;

// =============================================================================
const MODE = DEMO_MODE ? 'preview'
           : (TEST_RUN !== true ? 'live' : (TEST_PHONE.trim() !== '' ? 'test' : 'preview'));

const supabase_enabled = SUPABASE_URL.trim() !== '' && SUPABASE_SERVICE_KEY.trim() !== '';
const ats_enabled      = ATS_BASE_URL.trim() !== '' && ATS_TOKEN.trim() !== '';
const twilio_enabled   = TWILIO_ACCOUNT_SID.trim() !== '' && TWILIO_AUTH_TOKEN.trim() !== ''
                      && (TWILIO_FROM_NUMBER.trim() !== '' || TWILIO_MESSAGING_SID.trim() !== '');
const retell_enabled   = RETELL_API_KEY.trim() !== '' && RETELL_AGENT_ID.trim() !== '';

return [{
  json: {
    client_slug: CLIENT_SLUG,
    client_id:   CLIENT_ID,
    client_name: CLIENT_SLUG.charAt(0).toUpperCase() + CLIENT_SLUG.slice(1),

    supabase_url: SUPABASE_URL.replace(/\/+$/, ''),
    supabase_key: SUPABASE_SERVICE_KEY,
    supabase_enabled: supabase_enabled,
    dry_run_db: DRY_RUN_DB === true,

    ats_vendor: ATS_VENDOR,
    ats_base_url: ATS_BASE_URL.replace(/\/+$/, ''),
    ats_token: ATS_TOKEN,
    ats_fields: ATS_FIELDS,
    ats_enabled: ats_enabled,
    ats_exclude_statuses: ATS_EXCLUDE_STATUSES,
    ats_search_limit: ATS_CANDIDATE_SEARCH_LIMIT,

    ai_key: AI_API_KEY,
    ai_model: AI_MODEL,
    ai_effort: AI_EFFORT,
    ai_max_skills: AI_MAX_SKILLS,
    min_skills_before_ai: MIN_SKILLS_BEFORE_AI,
    ai_enabled: AI_API_KEY.trim() !== '',

    match: MATCH,
    min_match_score: MIN_MATCH_SCORE,
    enroll_top_n: ENROLL_TOP_N,

    sequence: SEQUENCE,
    quiet_hours_start: QUIET_HOURS_START,
    quiet_hours_end: QUIET_HOURS_END,
    send_on_weekends: SEND_ON_WEEKENDS,
    default_timezone: DEFAULT_TIMEZONE,
    runner_batch_size: RUNNER_BATCH_SIZE,
    daily_send_cap: DAILY_SEND_CAP,
    lease_seconds: LEASE_SECONDS,
    min_hours_between_touches: MIN_HOURS_BETWEEN_TOUCHES,

    twilio_sid: TWILIO_ACCOUNT_SID,
    twilio_token: TWILIO_AUTH_TOKEN,
    twilio_from: TWILIO_FROM_NUMBER,
    twilio_messaging_sid: TWILIO_MESSAGING_SID,
    twilio_status_callback: TWILIO_STATUS_CALLBACK,
    twilio_enabled: twilio_enabled,
    permanent_sms_errors: PERMANENT_SMS_ERRORS,

    retell_key: RETELL_API_KEY,
    retell_agent: RETELL_AGENT_ID,
    retell_from: RETELL_FROM_NUMBER,
    retell_secret: RETELL_WEBHOOK_SECRET,
    retell_enabled: retell_enabled,

    qualify: QUALIFY,
    opt_out_keywords: OPT_OUT_KEYWORDS,
    positive_keywords: POSITIVE_KEYWORDS,
    negative_keywords: NEGATIVE_KEYWORDS,

    calendar_provider: CALENDAR_PROVIDER,
    calendar_enabled: CALENDAR_PROVIDER !== 'none',
    recruiter_calendars: RECRUITER_CALENDARS,
    interview_minutes: INTERVIEW_MINUTES,
    booking_lead_hours: BOOKING_LEAD_HOURS,
    booking_window_days: BOOKING_WINDOW_DAYS,
    booking_hours: BOOKING_HOURS,

    slack_webhook_url: SLACK_WEBHOOK_URL,
    slack_enabled: SLACK_WEBHOOK_URL.trim() !== '',
    notify_recruiter_email: NOTIFY_RECRUITER_EMAIL === true,

    mode: MODE,
    test_phone: TEST_PHONE.trim(),
    demo_mode: DEMO_MODE === true,
    // Deliberately ANDed with DEMO_MODE here rather than trusted on its own, so the flag
    // cannot be left on by accident and quietly disable quiet hours in production.
    ignore_quiet_hours: DEMO_MODE === true && DEMO_ANY_HOUR === true,
    forced_preview: DEMO_MODE === true && TEST_RUN !== true,
    // The single flag every outbound gate reads. Nothing else decides whether to send.
    send_enabled: MODE !== 'preview',
    live_send: MODE === 'live',
    // Only a live run may touch the client's ATS or a recruiter's real calendar.
    writeback_enabled: MODE === 'live'
  }
}];

// Webhook security. This endpoint is a public URL that can opt a candidate out, cancel a
// campaign and write into the client's ATS, so anything arriving unsigned is refused.
//
// Two providers, two algorithms, both implemented properly:
//
//   Twilio   X-Twilio-Signature — HMAC-SHA1, base64, over the full request URL with the
//            POST parameters appended in alphabetical key order. Reconstructing that from
//            the parsed form body IS the documented algorithm, not an approximation.
//
//   Retell   X-Retell-Signature — HMAC-SHA256, hex, over the JSON payload. Retell's own
//            SDK signs JSON.stringify(body), so stringifying the parsed body matches.
//
// It fails CLOSED. If no secret is configured, or the platform gives us no way to compute
// an HMAC, a live run rejects the request rather than trusting it. Only preview mode is
// allowed to wave an unverified event through, and it says so in the output.
const cfg = $('config').first().json;
const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body !== undefined ? req.body : req;
const query = req.query || {};

const lower = {};
for (const k of Object.keys(headers)) lower[String(k).toLowerCase()] = headers[k];

const twilioSig = lower['x-twilio-signature'] || '';
const retellSig = lower['x-retell-signature'] || '';
const source = twilioSig ? 'twilio' : (retellSig ? 'retell' : 'unknown');

// Web Crypto is a global in the n8n sandbox and in Node 18+, so no require() and no
// instance env var is needed for this to work on n8n Cloud.
async function hmac(algo, secret, message, encoding) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(secret), { name: 'HMAC', hash: algo }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(message));
  const bytes = new Uint8Array(sig);
  if (encoding === 'hex') {
    let out = '';
    for (let i = 0; i < bytes.length; i++) out += bytes[i].toString(16).padStart(2, '0');
    return out;
  }
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

// Length-independent comparison. A timing attack on a webhook is unlikely; writing the
// comparison correctly costs three lines.
function safeEqual(a, b) {
  const x = String(a || '');
  const y = String(b || '');
  let diff = x.length ^ y.length;
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    diff |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  }
  return diff === 0;
}

const result = {
  _source: source,
  _verified: false,
  _reason: '',
  headers_seen: Object.keys(lower).filter((h) => h.indexOf('signature') !== -1),
  body: body,
  query: query
};

try {
  if (source === 'twilio') {
    if (!cfg.twilio_token) {
      result._reason = 'no TWILIO_AUTH_TOKEN configured — cannot verify';
    } else {
      // The URL Twilio signed. It must be the externally visible one; behind a proxy the
      // node sees http:// and the wrong host, which is the usual cause of a signature that
      // "should" match and does not.
      const url = cfg.twilio_status_callback
        || (lower['x-forwarded-proto'] || 'https') + '://' + (lower['x-forwarded-host']
            || lower.host || '') + (req.path || req.webhookUrl || '');
      const params = (body && typeof body === 'object') ? body : {};
      const signedString = Object.keys(params).sort().reduce(
        (acc, k) => acc + k + (params[k] === null || params[k] === undefined ? '' : params[k]),
        url);
      const expected = await hmac('SHA-1', cfg.twilio_token, signedString, 'base64');
      result._verified = safeEqual(expected, twilioSig);
      result._reason = result._verified ? 'twilio signature ok'
        : 'twilio signature mismatch — check that TWILIO_STATUS_CALLBACK in config is the '
          + 'exact public URL configured in the Twilio console, including https and any path';
      result._signed_url = url;
    }
  } else if (source === 'retell') {
    if (!cfg.retell_secret) {
      result._reason = 'no RETELL_WEBHOOK_SECRET configured — cannot verify';
    } else {
      const payload = typeof body === 'string' ? body : JSON.stringify(body);
      const expected = await hmac('SHA-256', cfg.retell_secret, payload, 'hex');
      const provided = String(retellSig).replace(/^v=/, '');
      result._verified = safeEqual(expected, provided);
      result._reason = result._verified ? 'retell signature ok' : 'retell signature mismatch';
    }
  } else {
    result._reason = 'no recognised signature header on the request';
  }
} catch (e) {
  result._reason = 'signature check errored: ' + String(e && e.message ? e.message : e);
}

// Preview may proceed unverified so the workflow can be demonstrated with a curl. A live
// run may not, ever.
result._allow = result._verified || (!cfg.live_send && !cfg.writeback_enabled);
result._unverified_but_allowed = result._allow && !result._verified;

return [{ json: result }];

// The request was not signed by anyone we trust. It is refused, logged, and answered with
// a 403 — and nothing downstream of this node ever sees it.
//
// This branch existing is the point. A public webhook that can opt a candidate out and
// write into a client's ATS has to be able to say no, and it has to say no by default when
// a secret is missing rather than when a secret is wrong.
const cfg = $('config').first().json;
const v = $input.first().json || {};

return [{
  json: {
    _outcome: 'signature rejected',
    source: v._source,
    reason: v._reason,
    signature_headers_present: v.headers_seen || [],
    signed_url_we_used: v._signed_url || '(n/a)',
    mode: cfg.mode,
    _http_status: 403,
    _next_step: v._source === 'twilio'
      ? 'Almost always the URL. Twilio signs the exact public URL it posted to, so behind '
        + 'a reverse proxy n8n sees the internal one and the HMAC will never match. Set '
        + 'TWILIO_STATUS_CALLBACK in config to the exact URL in the Twilio console.'
      : (v._source === 'retell'
        ? 'Check RETELL_WEBHOOK_SECRET matches the signing secret in the Retell dashboard.'
        : 'No signature header arrived at all. If this was a manual curl, that is expected '
          + '— set DEMO_MODE or TEST_RUN so preview lets unsigned requests through.')
  }
}];

// One endpoint, three kinds of event. This node normalises all of them into the same
// object so nothing downstream has to know which provider it came from.
//
//   twilio_sms      a candidate replied to a text
//   twilio_status   a delivery receipt (delivered / undelivered / failed)
//   retell_call     an AI screening call finished and was analysed
//
// It also decides the INTENT of an inbound message, and the order of those checks is the
// part that matters. Opt-out is tested first, on the raw text, before any AI is involved —
// because "stop calling me, I already told the last guy" contains both an opt-out and a
// sentence a classifier could easily read as engagement.
const cfg = $('config').first().json;
const v = $input.first().json || {};
const b = v.body || {};

const str = (x) => (x === null || x === undefined ? '' : String(x).trim());
const norm = (s) => str(s).toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();

function toE164(value) {
  const raw = str(value);
  const cleaned = raw.replace(/[\s()-]/g, '');
  if (/^\+[1-9]\d{7,14}$/.test(cleaned)) return cleaned;
  const digits = raw.replace(/\D/g, '');
  if (digits.length === 11 && digits[0] === '1') return '+' + digits;
  if (digits.length === 10) return '+1' + digits;
  return null;
}

let out = {
  _understood: false,
  source: v._source || 'unknown',
  event_type: '',
  provider_event_id: '',
  from_number: null,
  body_text: '',
  intent: 'unclear',
  _signature_verified: v._verified === true,
  _unverified_but_allowed: v._unverified_but_allowed === true
};

// ---------------------------------------------------------------- Twilio
if (b.MessageSid || b.SmsSid || b.MessageStatus || b.SmsStatus) {
  const status = str(b.MessageStatus || b.SmsStatus).toLowerCase();
  const hasText = b.Body !== undefined;

  if (hasText && !status) {
    out.source = 'twilio_sms';
    out.event_type = 'inbound_sms';
    out.provider_event_id = str(b.MessageSid || b.SmsSid);
    out.from_number = toE164(b.From);
    out.body_text = str(b.Body);
    out._understood = !!out.from_number;
  } else {
    out.source = 'twilio_status';
    out.event_type = status || 'status';
    out.provider_event_id = str(b.MessageSid || b.SmsSid) + ':' + status;
    out.from_number = toE164(b.To);
    out.delivery_status = status;
    out.error_code = str(b.ErrorCode) || null;
    // A delivery receipt is bookkeeping, not a reply. It updates the attempt row and
    // stops. The one exception is a hard failure, which retires the number.
    out._is_delivery_failure = ['undelivered', 'failed'].indexOf(status) !== -1;
    out._understood = true;
  }
}

// ---------------------------------------------------------------- Retell
else if (b.event || b.call || b.call_id) {
  const call = b.call || b;
  const ev = str(b.event || 'call_analyzed');
  out.source = 'retell_call';
  out.event_type = ev;
  out.provider_event_id = str(call.call_id || b.call_id);
  out.from_number = toE164(call.to_number || call.to || b.to_number);
  out.call_status = str(call.call_status || b.call_status);
  out.disconnect_reason = str(call.disconnection_reason || '');
  out.duration_seconds = Number(call.duration_ms ? call.duration_ms / 1000
    : (call.duration_seconds || 0)) || 0;
  out.transcript = str(call.transcript).slice(0, 8000);
  out.recording_url = str(call.recording_url);

  // The structured answers. This is the ONLY part of the call the engine makes a decision
  // from — the transcript is stored for a human, and the summary is stored for a human,
  // and neither is parsed. An LLM that writes prose into a decision path is a bug.
  const analysis = call.call_analysis || b.call_analysis || {};
  out.call_summary = str(analysis.call_summary).slice(0, 2000);
  out.answers = analysis.custom_analysis_data || analysis.extracted || {};
  out.agent_sentiment = str(analysis.user_sentiment);

  // Only a call that was actually analysed carries answers. `call_started` and
  // `call_ended` arrive first and must not be mistaken for a screening result.
  out._is_final = ev === 'call_analyzed';
  out._no_answer = ['no-answer', 'voicemail', 'dial_no_answer', 'dial_busy', 'dial_failed']
    .indexOf(out.disconnect_reason) !== -1
    || ['no_answer', 'busy', 'failed'].indexOf(out.call_status) !== -1;
  out._understood = !!out.provider_event_id;
}

// ---------------------------------------------------------------- Intent
// Only inbound text gets an intent. Word-boundary matching, so "not interested" is not
// read as "interested" and a message containing "stopping by" is not an opt-out.
if (out.source === 'twilio_sms') {
  const text = norm(out.body_text);
  const words = text.split(' ');
  const containsPhrase = (list) => list.some((p) => {
    const phrase = norm(p);
    if (!phrase) return false;
    if (phrase.indexOf(' ') !== -1) return text.indexOf(phrase) !== -1;
    return words.indexOf(phrase) !== -1;
  });

  if (containsPhrase(cfg.opt_out_keywords)) out.intent = 'opt_out';
  else if (containsPhrase(cfg.negative_keywords)) out.intent = 'not_interested';
  else if (containsPhrase(cfg.positive_keywords)) out.intent = 'interested';
  else if (text.indexOf('?') !== -1 || out.body_text.indexOf('?') !== -1) out.intent = 'question';
  else out.intent = 'unclear';

  // Whatever the intent, an inbound message stops the sequence. Someone who wrote back is
  // a conversation, and a robot texting over the top of a human reply is the single most
  // visible way this kind of system embarrasses an agency.
  out._stop_sequence = true;
}

if (out.source === 'retell_call') {
  out._stop_sequence = out._is_final && !out._no_answer;
}

out.client_id = cfg.client_id || null;
out.received_at = new Date().toISOString();
out._raw = b;

return [{ json: out }];

// A signed, valid event that this workflow deliberately does nothing with. Delivery
// receipts, `call_started`, `call_ended` and unanswered calls all land here.
//
// They are answered 200 — refusing them makes Twilio and Retell retry the same event for
// hours — recorded, and dropped. Being explicit about the ones we ignore is what keeps the
// execution list readable: a run that ends here is not a run that broke.
const ev = $input.first().json || {};

let why;
if (ev.source === 'twilio_status') {
  why = ev._is_delivery_failure
    ? 'delivery failure (' + ev.delivery_status + (ev.error_code ? ', code ' + ev.error_code : '')
      + ') — the attempt row is updated, the ladder is not advanced'
    : 'delivery receipt (' + ev.delivery_status + ') — bookkeeping only, not a reply';
} else if (ev.source === 'retell_call' && !ev._is_final) {
  why = 'Retell "' + ev.event_type + '" — the screening result arrives on call_analyzed, '
    + 'and acting on an earlier event would qualify somebody from a call still in progress';
} else if (ev._no_answer) {
  why = 'the call was not answered (' + (ev.disconnect_reason || ev.call_status)
    + ') — not a rejection. The enrollment stays on its rung and the ladder continues.';
} else if (!ev._understood) {
  why = 'the payload did not match any shape this endpoint knows';
} else {
  why = 'no action defined for intent "' + ev.intent + '"';
}

return [{
  json: {
    _outcome: 'event ignored',
    source: ev.source,
    event_type: ev.event_type,
    intent: ev.intent,
    why: why,
    provider_event_id: ev.provider_event_id,
    _http_status: 200,
    _still_logged: true,
    _next_step: 'Every event is written to inbound_events regardless, so the full history '
      + 'of what arrived is queryable even for the ones nothing was done about.'
  }
}];

// Somebody said stop. This node builds everything that has to happen, and the important
// property is that it is ONE database call — `stop_all_outreach(client_id, phone)` — not a
// sequence of four that could half-succeed.
//
// Inside that function, in one transaction: the number goes on the opt-out list, and every
// enrollment for that number in any campaign has its next_attempt_at set to null. There is
// no window in which the opt-out is recorded but the queue still holds a scheduled text.
//
// Keyed on the PHONE, not the candidate. One human with three ATS records opts out once.
const cfg = $('config').first().json;
const ev = $input.first().json || {};

const phone = ev.from_number;

// The reply. Legally you may send exactly one confirmation to someone who opted out, and
// nothing after it. It is deliberately plain text with no link and no question.
const confirmation = 'You have been unsubscribed and will not receive further messages '
  + 'from ' + (cfg.client_name || 'us') + '. No further action is needed.';

return [{
  json: {
    _outcome: 'opt-out',
    phone_e164: phone,
    client_id: cfg.client_id || null,
    reason: ev.source === 'retell_call' ? 'asked to stop on a call' : 'SMS keyword',
    matched_text: (ev.body_text || '').slice(0, 200),

    // The single RPC call the next node makes.
    rpc: {
      p_client_id: cfg.client_id || null,
      p_phone: phone,
      p_reason: ev.source === 'retell_call' ? 'voice' : 'sms_keyword'
    },

    // Twilio auto-replies to STOP itself for standard keywords on a US long code, so
    // sending our own confirmation would double-text them. It is only sent for the
    // non-standard phrases Twilio does not catch ("take me off", "remove me").
    _send_confirmation: !/^(stop|stopall|unsubscribe|cancel|end|quit)$/i
      .test(String(ev.body_text || '').trim()),
    confirmation_text: confirmation,

    // Queued for the ATS so the recruiter sees it in the place they actually work, rather
    // than only in a database they never open.
    ats_note: {
      action: 'add_note',
      payload: {
        action: 'Opt-out',
        comments: 'Candidate opted out of SMS/voice outreach on '
          + new Date().toISOString().slice(0, 10)
          + (ev.body_text ? (' — replied: "' + String(ev.body_text).slice(0, 120) + '"') : '')
          + '. All automated outreach for this number has been stopped across every '
          + 'campaign. Do not re-add manually.'
      }
    },

    _next_step: 'Nothing else in the engine can contact this number. The queue view filters '
      + 'on the opt-out table, so even a campaign launched tomorrow will exclude them.'
  }
}];

// An opt-out arrived and there is no database to record it in.
//
// This is the one STOP node in the engine that is genuinely uncomfortable, and it is
// written that way on purpose. Every other unconfigured integration degrades harmlessly —
// a missing Twilio key means nothing sends. A missing opt-out record means the request was
// received and forgotten, which is the failure that gets a staffing agency a TCPA letter.
//
// It cannot bite in practice: with no database there is no queue, so nothing was scheduled
// to send to them in the first place. But the moment a database exists, this branch stops
// being reachable, and until then the node says out loud what was not stored.
const cfg = $('config').first().json;
const j = $input.first().json || {};

return [{
  json: {
    _outcome: 'OPT-OUT NOT PERSISTED — no database configured',
    _severity: 'would be serious in production',
    phone_e164: j.phone_e164,
    reason: j.reason,
    matched_text: j.matched_text,

    would_have_called: 'stop_all_outreach(' + (cfg.client_id || 'null') + ', '
      + j.phone_e164 + ')',
    which_would: [
      'insert the number into opt_outs, keyed on the phone so it covers every ATS record '
        + 'that person has',
      'set next_attempt_at = null on every enrollment for that number, in every campaign',
      'both in one transaction, so there is no window where the opt-out is recorded but a '
        + 'text is still queued'
    ],

    _safe_because: 'With no database there is no queue, so nothing was scheduled to send to '
      + 'this number and nothing will. The gap is real but it is not currently reachable.',
    _next_step: 'Fill in SUPABASE_URL and SUPABASE_SERVICE_KEY. This branch is unreachable '
      + 'from that point on.'
  }
}];

// The decision. Deterministic, auditable, and identical every time it runs on the same
// answers — which is the property that lets a staffing manager argue with it.
//
// The AI's job is to fill in the blanks. This node's job is to decide. The separation is
// deliberate: the Retell agent is asked structured questions and returns typed answers,
// and the pass/fail is computed from QUALIFY in the config node, so changing the bar is a
// config edit rather than a prompt rewrite, and last month's decisions can be re-explained.
//
// The rule that matters most: null never passes. A question the agent could not establish
// is not an assumed yes.
const cfg = $('config').first().json;
const ev = $input.first().json || {};
const q = cfg.qualify || { must: [], score: [], pass_mark: 0, review_band: 0 };

// Answers come from the Retell analysis, or from an SMS conversation that got far enough.
// Both arrive as a flat object of typed values.
const answers = Object.assign({}, ev.answers || {});

// An SMS "YES" is interest, not qualification. It is recorded as one answered question out
// of several, and it will not on its own clear a `must` list that asks about work
// authorisation and a start date.
if (ev.source === 'twilio_sms') {
  if (ev.intent === 'interested') answers.interested = true;
  if (ev.intent === 'not_interested') answers.interested = false;
}

const coerce = (v) => {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['true', 'yes', 'y', 'confirmed'].indexOf(s) !== -1) return true;
  if (['false', 'no', 'n', 'declined'].indexOf(s) !== -1) return false;
  if (['unknown', 'unclear', 'n/a', 'na', 'not stated', 'null'].indexOf(s) !== -1) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : String(v);
};

function test(rule, value) {
  if (value === null) return { pass: false, why: 'not established' };
  if (rule.equals !== undefined) {
    return { pass: value === rule.equals, why: 'answered ' + JSON.stringify(value) };
  }
  if (rule.gte !== undefined) {
    const n = Number(value);
    return { pass: Number.isFinite(n) && n >= rule.gte, why: String(value) + ' vs >= ' + rule.gte };
  }
  if (rule.lte !== undefined) {
    const n = Number(value);
    return { pass: Number.isFinite(n) && n <= rule.lte, why: String(value) + ' vs <= ' + rule.lte };
  }
  return { pass: false, why: 'no comparison in the rule' };
}

const musts = [];
let failedMust = null;
for (const rule of q.must || []) {
  const value = coerce(answers[rule.key]);
  const r = test(rule, value);
  musts.push({ label: rule.label, key: rule.key, value: value, passed: r.pass, detail: r.why });
  if (!r.pass && !failedMust) failedMust = rule.label + ' (' + r.why + ')';
}

let score = 0;
const scored = [];
for (const rule of q.score || []) {
  const value = coerce(answers[rule.key]);
  const r = test(rule, value);
  if (r.pass) score += Number(rule.points) || 0;
  scored.push({ label: rule.label, key: rule.key, value: value,
    passed: r.pass, points: r.pass ? (rule.points || 0) : 0, detail: r.why });
}

const answered = musts.concat(scored).filter((x) => x.value !== null).length;
const total = musts.length + scored.length;

const passMark = Number(q.pass_mark) || 0;
const band = Number(q.review_band) || 0;

let outcome;
let reason;

if (ev._no_answer) {
  outcome = 'no_answer';
  reason = 'the call was not answered — this is not a rejection, the ladder continues';
} else if (ev.intent === 'not_interested' || answers.interested === false) {
  outcome = 'not_qualified';
  reason = 'said they are not interested';
} else if (failedMust) {
  // Everything that failed only because the agent never got an answer goes to a human
  // rather than being rejected. A dropped call is not a "no".
  const onlyUnestablished = musts.filter((m) => !m.passed).every((m) => m.value === null);
  outcome = onlyUnestablished && answered > 0 ? 'needs_review' : 'not_qualified';
  reason = onlyUnestablished
    ? 'could not establish: ' + musts.filter((m) => !m.passed).map((m) => m.label).join(', ')
    : 'failed a requirement — ' + failedMust;
} else if (score >= passMark) {
  outcome = 'qualified';
  reason = 'met every requirement and scored ' + score + ' of ' + passMark;
} else if (score >= passMark - band) {
  outcome = 'needs_review';
  reason = 'scored ' + score + ', within ' + band + ' of the ' + passMark + ' pass mark';
} else {
  outcome = 'not_qualified';
  reason = 'scored ' + score + ', below the ' + passMark + ' pass mark';
}

// A one-line sentence a recruiter can read without opening anything. This is what goes in
// the Slack message and into the ATS note.
const highlights = scored.filter((s) => s.passed).map((s) => s.label);
const gaps = scored.filter((s) => !s.passed && s.value !== null).map((s) => s.label);

return [{
  json: Object.assign({}, ev, {
    qualification: {
      outcome: outcome,
      reason: reason,
      score: score,
      pass_mark: passMark,
      questions_answered: answered,
      questions_total: total,
      must: musts,
      scored: scored,
      answers: answers,
      evaluated_at: new Date().toISOString(),
      // Stamped so a decision made last quarter can be re-explained against the rules that
      // were in force at the time, not the ones in config today.
      criteria_version: JSON.stringify(q).length
    },
    _qualified: outcome === 'qualified',
    _needs_review: outcome === 'needs_review',
    _no_answer: outcome === 'no_answer',
    _headline: (ev.candidate_name || 'Candidate') + ' — ' + outcome.replace('_', ' ')
      + ' (' + score + '/' + passMark + ')',
    _highlights: highlights,
    _gaps: gaps,
    _enrollment_status: outcome === 'qualified' ? 'qualified'
      : (outcome === 'no_answer' ? 'active'
        : (outcome === 'needs_review' ? 'responded' : 'not_qualified'))
  })
}];

// Screened and not moving forward — or screened and needing a human. Either way this is a
// real outcome that gets written into the ATS, not a dead end.
//
// The distinction between the two matters commercially. "Not qualified" closes a candidate
// out. "Needs review" is a person the AI could not finish establishing something about,
// and quietly rejecting those is how an agency loses good candidates to an automation
// nobody audits.
const ev = $input.first().json || {};
const q = ev.qualification || {};

const unanswered = (q.must || []).concat(q.scored || [])
  .filter((x) => x.value === null)
  .map((x) => x.label);

return [{
  json: Object.assign({}, ev, {
    _outcome: q.outcome,
    headline: ev._headline,
    reason: q.reason,
    score: q.score,
    pass_mark: q.pass_mark,
    answered: q.questions_answered + ' of ' + q.questions_total,
    could_not_establish: unanswered,
    failed_requirements: (q.must || []).filter((m) => !m.passed)
      .map((m) => m.label + ' — ' + m.detail),
    _needs_a_human: q.outcome === 'needs_review',
    _next_step: q.outcome === 'needs_review'
      ? 'This one is queued for a recruiter, not rejected. The ATS note carries every '
        + 'answer the agent did get, so the follow-up call starts from something.'
      : 'Written back to the ATS with the reason. The candidate stays in the database and '
        + 'is eligible for a different job order tomorrow — the outcome is scoped to this '
        + 'campaign, not to the person.'
  })
}];

// Chooses who the interview is with and when. Both answers are deterministic, because a
// booking that lands in the wrong recruiter's calendar is worse than no booking.
//
// The recruiter is the one on the JOB ORDER, not a round-robin. A candidate who was texted
// about Dana's forklift role and booked with someone else has to be re-explained to two
// people, and the client hears about it.
const cfg = $('config').first().json;
const ev = $input.first().json || {};

const recruiterEmail = String(ev.recruiter_email || '').toLowerCase();
const calendarId = (cfg.recruiter_calendars || {})[recruiterEmail] || recruiterEmail;

const tz = ev.candidate_timezone || cfg.default_timezone;
const minutes = Number(cfg.interview_minutes) || 30;
const leadHours = Number(cfg.booking_lead_hours) || 18;
const windowDays = Number(cfg.booking_window_days) || 5;
const hours = (cfg.booking_hours || [9, 10, 11, 13, 14, 15, 16]).map(Number);

function partsIn(date, zone) {
  try {
    const f = new Intl.DateTimeFormat('en-US', {
      timeZone: zone, hour: 'numeric', hour12: false, weekday: 'short'
    });
    const p = f.formatToParts(date);
    return {
      hour: Number((p.find((x) => x.type === 'hour') || {}).value) % 24,
      weekday: (p.find((x) => x.type === 'weekday') || {}).value
    };
  } catch (e) {
    return { hour: date.getUTCHours(), weekday: 'Mon' };
  }
}

// Walk forward hour by hour from the lead time. The first slot that is a weekday, inside
// the recruiter's booking hours, wins. Proposing rather than booking blind is deliberate:
// this is a candidate-side hold, and the free/busy check happens in the calendar node,
// which will refuse a genuine clash.
const earliest = new Date(Date.now() + leadHours * 3600 * 1000);
let slot = null;
for (let h = 0; h < windowDays * 24; h++) {
  const t = new Date(earliest.getTime() + h * 3600 * 1000);
  const p = partsIn(t, tz);
  if (p.weekday === 'Sat' || p.weekday === 'Sun') continue;
  if (hours.indexOf(p.hour) === -1) continue;
  t.setUTCMinutes(0, 0, 0);
  slot = t;
  break;
}

if (!slot) slot = new Date(earliest.getTime() + 24 * 3600 * 1000);

const ends = new Date(slot.getTime() + minutes * 60 * 1000);
const qual = ev.qualification || {};

const when = (() => {
  try {
    return new Intl.DateTimeFormat('en-US', {
      timeZone: tz, weekday: 'long', month: 'short', day: 'numeric',
      hour: 'numeric', minute: '2-digit'
    }).format(slot) + ' (' + tz.split('/').pop().replace('_', ' ') + ')';
  } catch (e) { return slot.toISOString(); }
})();

return [{
  json: Object.assign({}, ev, {
    booking: {
      recruiter_email: recruiterEmail,
      recruiter_name: ev.recruiter_name || 'the recruiting team',
      calendar_id: calendarId,
      calendar_provider: cfg.calendar_provider,
      starts_at: slot.toISOString(),
      ends_at: ends.toISOString(),
      timezone: tz,
      human_time: when,
      summary: 'Interview: ' + (ev.candidate_name || 'candidate') + ' — '
        + (ev.job_title || 'role'),
      description: [
        (ev.candidate_name || 'Candidate') + ' — ' + (ev.job_title || 'role'),
        '',
        'Qualified by AI screening on ' + new Date().toISOString().slice(0, 10) + '.',
        'Score ' + qual.score + '/' + qual.pass_mark + '. ' + (qual.reason || ''),
        '',
        'Strengths: ' + ((ev._highlights || []).join(', ') || 'none recorded'),
        'Gaps: ' + ((ev._gaps || []).join(', ') || 'none recorded'),
        '',
        'Phone: ' + (ev.from_number || 'unknown'),
        ev.call_summary ? ('\nCall summary:\n' + ev.call_summary) : '',
        ev.recording_url ? ('\nRecording: ' + ev.recording_url) : ''
      ].filter(Boolean).join('\n'),
      attendees: [recruiterEmail].filter(Boolean)
    },
    _recruiter_missing: !recruiterEmail,
    _booking_warning: !recruiterEmail
      ? 'The job order carried no recruiter email, so there is no calendar to book into. '
        + 'The candidate is still marked qualified and the recruiter notification still '
        + 'goes out — it just has to be booked by hand.'
      : ''
  })
}];

// Qualified, but nothing was put in a calendar. Three reasons, and the node says which.
//
// It is deliberately NOT an error branch. A qualified candidate with no booking is still a
// qualified candidate the recruiter must hear about within minutes, so this path carries
// on to the notification and the ATS write-back exactly like the booked path does.
const cfg = $('config').first().json;
const ev = $input.first().json || {};
const b = ev.booking || {};

const why = !cfg.calendar_enabled
  ? 'CALENDAR_PROVIDER is set to "none".'
  : (ev._recruiter_missing
    ? 'The job order carried no recruiter email, so there is no calendar to book into. '
      + 'Check ATS_FIELDS.job.recruiter_mail for this vendor.'
    : (!cfg.writeback_enabled
      ? 'This run is ' + cfg.mode + '. Only a live run creates a real calendar event.'
      : 'The calendar node did not return an event.'));

return [{
  json: Object.assign({}, ev, {
    _outcome: 'qualified — not booked',
    why: why,
    proposed_slot: b.starts_at
      ? { starts_at: b.starts_at, human_time: b.human_time, recruiter: b.recruiter_email }
      : null,
    _next_step: 'The recruiter is still notified and the ATS note is still written. The '
      + 'slot above is the one the engine would have taken, so booking it by hand takes a '
      + 'few seconds rather than a conversation.'
  })
}];

// Everything that goes back into the client's ATS, and the notification that goes to the
// recruiter.
//
// The write-back is QUEUED to the ats_writebacks table before it is attempted. That is the
// difference between a Bullhorn outage delaying a note and losing it: the row exists with
// status 'pending', a retry sweep picks it up, and the idempotency key means a note is
// never written twice however many times it is retried.
//
// A recruiter who works in Bullhorn all day will not open a Supabase dashboard. If the
// outcome is not in the ATS, it did not happen.
const cfg = $('config').first().json;
const ev = $input.first().json || {};
const q = ev.qualification || {};
const b = ev.booking || {};

const today = new Date().toISOString().slice(0, 10);
const atsId = ev.ats_candidate_id || ev.candidate_ats_id || '';

// Stable per candidate, per outcome, per day. A retry writes the same row; a genuinely new
// outcome tomorrow writes a new one.
const key = (action) => ['wb', cfg.client_slug, atsId, action, q.outcome || 'none', today].join(':');

const answered = (q.must || []).concat(q.scored || [])
  .filter((x) => x.value !== null)
  .map((x) => '  - ' + x.label + ': ' + JSON.stringify(x.value) + (x.passed ? '' : '  (miss)'));

const note = [
  'AI screening — ' + String(q.outcome || 'unknown').replace('_', ' ').toUpperCase(),
  '',
  'Role: ' + (ev.job_title || 'unknown'),
  'Channel: ' + (ev.source === 'retell_call' ? 'AI voice call' : 'SMS'),
  'Score: ' + q.score + ' / ' + q.pass_mark + '  (' + q.questions_answered + ' of '
    + q.questions_total + ' questions answered)',
  'Verdict: ' + (q.reason || ''),
  '',
  'Answers:',
  ...(answered.length ? answered : ['  - none recorded']),
  ''
];

if (b.starts_at) {
  note.push('Interview booked: ' + b.human_time + ' with ' + b.recruiter_name, '');
}
if (ev.call_summary) note.push('Call summary:', ev.call_summary, '');
if (ev.recording_url) note.push('Recording: ' + ev.recording_url);
if (ev.transcript) {
  note.push('', 'Transcript is stored against the attempt in the operating database.');
}

// The status a candidate moves to. Deliberately conservative: the engine advances people
// through screening states and never touches Placed, Submitted, or anything a human owns.
const STATUS_MAP = {
  qualified: 'Qualified - Interview Scheduled',
  needs_review: 'Screened - Needs Review',
  not_qualified: 'Screened - Not a Fit',
  no_answer: null
};
const newStatus = STATUS_MAP[q.outcome] || null;

const writebacks = [{
  client_id: cfg.client_id || null,
  ats_candidate_id: atsId,
  action: 'add_note',
  payload: { action: 'AI Screening', comments: note.join('\n').slice(0, 8000) },
  status: 'pending',
  idempotency_key: key('add_note')
}];

if (newStatus) {
  writebacks.push({
    client_id: cfg.client_id || null,
    ats_candidate_id: atsId,
    action: 'update_status',
    payload: { status: newStatus },
    status: 'pending',
    idempotency_key: key('update_status')
  });
}

// ---------------------------------------------------------------- the recruiter's message
const lines = [
  q.outcome === 'qualified'
    ? '*Qualified candidate ready* — ' + (ev.job_title || 'your role')
    : '*Candidate needs a look* — ' + (ev.job_title || 'your role'),
  '',
  (ev.candidate_name || 'Candidate') + '  ·  ' + (ev.from_number || 'no number')
    + '  ·  score ' + q.score + '/' + q.pass_mark,
  q.reason || ''
];

if ((ev._highlights || []).length) lines.push('', 'Strengths: ' + ev._highlights.join(', '));
if ((ev._gaps || []).length) lines.push('Gaps: ' + ev._gaps.join(', '));
if (b.starts_at) lines.push('', 'Booked: ' + b.human_time);
else if (ev._recruiter_missing) {
  lines.push('', 'No recruiter calendar on this job order — this one needs booking by hand.');
}
if (ev.call_summary) lines.push('', '> ' + ev.call_summary.slice(0, 400));
if (ev.recording_url) lines.push('', 'Recording: ' + ev.recording_url);

return [{
  json: Object.assign({}, ev, {
    _write: cfg.writeback_enabled,
    _why_not: cfg.writeback_enabled ? ''
      : 'Only a live run writes into the client ATS or a real calendar. This run is '
        + cfg.mode + '.',
    writebacks: writebacks,
    ats_note_preview: note.join('\n'),
    new_ats_status: newStatus,
    slack_payload: { text: lines.filter((l) => l !== undefined).join('\n') },
    recruiter_email_subject: (q.outcome === 'qualified' ? 'Qualified: ' : 'Needs review: ')
      + (ev.candidate_name || 'candidate') + ' — ' + (ev.job_title || 'role'),
    recruiter_email_body: lines.join('\n').replace(/\*/g, '')
  })
}];

// The outcome was decided but nothing was written into the client's ATS.
//
// Only a LIVE run may write into a client's system. A preview or test run does everything
// else — qualifies, picks a slot, builds the note — and stops here with the note it would
// have written, which is exactly what you want on screen when a client asks what lands in
// their Bullhorn.
const cfg = $('config').first().json;
const j = $input.first().json || {};

return [{
  json: Object.assign({}, j, {
    _outcome: 'write-back skipped',
    _why: j._why_not || ('this run is ' + cfg.mode),
    would_have_written: (j.writebacks || []).map((w) => ({
      action: w.action,
      ats_candidate_id: w.ats_candidate_id,
      idempotency_key: w.idempotency_key
    })),
    the_note_it_would_write: j.ats_note_preview,
    the_status_it_would_set: j.new_ats_status,
    _next_step: 'Set TEST_RUN = false (and DEMO_MODE = false) to write for real. The rows '
      + 'are queued to ats_writebacks first, so an ATS outage delays them rather than '
      + 'losing them.'
  })
}];

// What Twilio and Retell get back, and how fast.
//
// Twilio gives a webhook 15 seconds and Retell about 10. An ATS write-back behind a slow
// OAuth refresh can take longer than that on its own, and a timed-out webhook is retried —
// which is how one candidate reply becomes four identical ATS notes.
//
// So this responds immediately with the minimum the provider needs. Everything slow
// downstream of it is already done by the time this node runs in the happy path, and where
// it is not, the queue in `ats_writebacks` carries it.
const j = $input.first().json || {};
const status = Number(j._http_status) || 200;

// Empty TwiML: acknowledged, no auto-reply. Any reply we do want to send goes out through
// the API instead, so it is logged as an attempt like every other outbound message rather
// than vanishing into a webhook response nothing records.
const twiml = '<?xml version="1.0" encoding="UTF-8"?><Response></Response>';

const isTwilio = String(j.source || '').indexOf('twilio') === 0;

return [{
  json: {
    _http_status: status,
    _content_type: isTwilio ? 'text/xml' : 'application/json',
    body: isTwilio ? twiml : JSON.stringify({
      ok: status < 400,
      outcome: j._outcome || 'processed',
      handled_at: new Date().toISOString()
    }),
    // Echoed so the execution list shows what was decided without opening three nodes.
    _summary: [j.source, j._outcome, j.headline || j.why || j.reason]
      .filter(Boolean).join(' · ')
  }
}];
